GUEST_REPO = Path("/mnt/rdf4j-ro")
GUEST_M2 = Path("/mnt/m2-ro")
JAVA_CLASS_MAJOR = 69


def create_fresh_directory(path: Path) -> Path:
    """Create exactly one new output root; never reuse, clear, or follow it."""
    requested = path.expanduser()
    if not requested.is_absolute():
        requested = Path.cwd() / requested
    if requested.name in ("", ".", "..") or requested == Path(requested.anchor):
        raise ValueError(f"output root must name a new child directory: {requested}")
    parent = requested.parent.resolve(strict=True)
    if not parent.is_dir():
        raise FileNotFoundError(f"output parent must be an existing directory: {parent}")
    path = parent / requested.name
    if path.exists() or path.is_symlink():
        raise FileExistsError(f"refusing pre-existing or unsafe output root: {path}")
    path.mkdir(mode=0o700)
    return path


def require_regular_file(path: Path, label: str) -> Path:
    resolved = path.expanduser().resolve(strict=True)
    info = resolved.stat()
    if not stat.S_ISREG(info.st_mode):
        raise ValueError(f"{label} must be a regular file: {resolved}")
    return resolved


def require_executable(path: Path, label: str) -> Path:
    resolved = require_regular_file(path, label)
    if not os.access(resolved, os.X_OK):
        raise ValueError(f"{label} is not executable: {resolved}")
    return resolved


def sha256_file(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as stream:
        for block in iter(lambda: stream.read(1024 * 1024), b""):
            digest.update(block)
    return digest.hexdigest()


def write_json_exclusive(path: Path, value: Any) -> None:
    payload = json.dumps(value, indent=2, sort_keys=True) + "\n"
    with path.open("x", encoding="utf-8") as stream:
        stream.write(payload)
        stream.flush()
        os.fsync(stream.fileno())


def write_text_exclusive(path: Path, value: str) -> None:
    with path.open("x", encoding="utf-8") as stream:
        stream.write(value)
        stream.flush()
        os.fsync(stream.fileno())


def copy_file_exclusive(source: Path, destination: Path) -> None:
    source = require_regular_file(source, "copy source")
    flags = os.O_WRONLY | os.O_CREAT | os.O_EXCL
    fd = os.open(destination, flags, 0o600)
    try:
        with source.open("rb") as src, os.fdopen(fd, "wb", closefd=False) as dst:
            shutil.copyfileobj(src, dst, 1024 * 1024)
            dst.flush()
            os.fsync(dst.fileno())
    except BaseException:
        os.close(fd)
        raise
    else:
        os.close(fd)


def copy_and_hash(source: Path, destination: Path) -> dict[str, Any]:
    source = require_regular_file(source, "image source")
    source_hash = sha256_file(source)
    copy_file_exclusive(source, destination)
    copied_hash = sha256_file(destination)
    if source_hash != copied_hash:
        raise IOError(f"copy checksum mismatch for {source}")
    return {"path": str(destination), "bytes": destination.stat().st_size,
            "sha256": copied_hash, "source_sha256": source_hash}


def class_major(path: Path) -> int:
    with path.open("rb") as stream:
        header = stream.read(8)
    if len(header) != 8 or header[:4] != b"\xca\xfe\xba\xbe":
        raise ValueError(f"not a Java class file: {path}")
    return int.from_bytes(header[6:8], "big")


def build_artifact_manifest(repo_root: Path) -> dict[str, Any]:
    repo_root = repo_root.resolve(strict=True)
    class_roots = {
        "main": repo_root / "core/sail/lmdb/target/classes",
        "test": repo_root / "core/sail/lmdb/target/test-classes",
    }
    records = []
    for label, class_root in class_roots.items():
        if not class_root.is_dir():
            raise FileNotFoundError(f"missing compiled class directory: {class_root}")
        class_paths = sorted(class_root.rglob("*.class"))
        if not class_paths:
            raise FileNotFoundError(f"compiled class directory is empty: {class_root}")
        for path in class_paths:
            major = class_major(path)
            if major != JAVA_CLASS_MAJOR:
                raise ValueError(f"{path} has class major {major}; guest requires Java 25 class major {JAVA_CLASS_MAJOR}")
            records.append({"output": label, "path": str(path.relative_to(repo_root)),
                            "size": path.stat().st_size, "sha256": sha256_file(path),
                            "java_class_major": major})
    required_classes = {
        "LmdbStore": "core/sail/lmdb/target/classes/org/eclipse/rdf4j/sail/lmdb/LmdbStore.class",
        "LmdbSailStore": "core/sail/lmdb/target/classes/org/eclipse/rdf4j/sail/lmdb/LmdbSailStore.class",
        "LmdbCrashRecoveryTest": "core/sail/lmdb/target/test-classes/org/eclipse/rdf4j/sail/lmdb/LmdbCrashRecoveryTest.class",
        "CrashWriterMain": "core/sail/lmdb/target/test-classes/org/eclipse/rdf4j/sail/lmdb/LmdbCrashRecoveryTest$CrashWriterMain.class",
    }
    paths = {record["path"] for record in records}
    missing = set(required_classes.values()) - paths
    if missing:
        raise FileNotFoundError("missing required LMDB crash-test classes: " + ", ".join(sorted(missing)))
    return {"guest_jdk_major": 25, "java_class_major": JAVA_CLASS_MAJOR,
            "main_class_count": sum(record["output"] == "main" for record in records),
            "test_class_count": sum(record["output"] == "test" for record in records),
            "required_classes": required_classes, "compiled_classes": records}


def guest_classpath(host_classpath_file: Path, repo_root: Path, *,
                    native_classifier: str = "linux-arm64") -> tuple[str, dict[str, Any]]:
    """Map host classpath entries to the two read-only 9p shares."""
    if native_classifier not in {"linux", "linux-arm64", "linux-ppc64le"}:
        raise ValueError(f"unsupported Linux guest native classifier: {native_classifier}")
    host_classpath_file = require_regular_file(host_classpath_file, "host classpath file")
    repo_root = repo_root.resolve(strict=True)
    m2_root = (repo_root / ".m2_repo").resolve(strict=True)
    raw = host_classpath_file.read_text(encoding="utf-8").strip()
    if not raw or "\n" in raw or "\r" in raw:
        raise ValueError("host classpath file must contain one nonempty path-separator-delimited line")
    entries: list[str] = []
    host_inputs: list[dict[str, Any]] = []
    filtered_native: list[str] = []
    for raw_entry in raw.split(os.pathsep):
        if not raw_entry:
            raise ValueError("host classpath contains an empty entry")
        host_entry = Path(raw_entry).expanduser().resolve(strict=True)
        name = host_entry.name
        if "-natives-" in name and not name.endswith(f"-natives-{native_classifier}.jar"):
            filtered_native.append(str(host_entry))
            continue
        try:
            relative_m2 = host_entry.relative_to(m2_root)
            guest_entry = GUEST_M2 / relative_m2
        except ValueError:
            try:
                relative_repo = host_entry.relative_to(repo_root)
            except ValueError as error:
                raise ValueError(f"classpath entry is outside the repository and .m2_repo: {host_entry}") from error
            guest_entry = GUEST_REPO / relative_repo
        entries.append(str(guest_entry))
        record = {"host_path": str(host_entry), "guest_path": str(guest_entry)}
        if host_entry.is_file():
            record["sha256"] = sha256_file(host_entry)
            record["size"] = host_entry.stat().st_size
        host_inputs.append(record)
    if not any(path.endswith("/core/sail/lmdb/target/test-classes") for path in entries):
        raise ValueError("classpath must include LMDB target/test-classes")
    if not any(path.endswith("/core/sail/lmdb/target/classes") for path in entries):
        raise ValueError("classpath must include LMDB target/classes")
    if not any("lwjgl-lmdb-" in path and path.endswith(f"-natives-{native_classifier}.jar") for path in entries):
        raise ValueError(f"classpath must include the Linux {native_classifier} LMDB native library jar")
    return os.pathsep.join(entries), {
        "source_classpath_file": str(host_classpath_file),
        "source_classpath_sha256": sha256_file(host_classpath_file),
        "mapped_entries": host_inputs,
        "native_classifier": native_classifier,
        "filtered_native_jars": filtered_native,
        "guest_classpath_entry_count": len(entries),
    }


def validate_qemu_arguments(args: Sequence[str]) -> None:
    """Reject QEMU options that suppress or bypass the NBD flush contract."""
    joined = "\n".join(args).lower()
    if "-snapshot" in args:
        raise ValueError("QEMU -snapshot is not permitted for the data-durability tier")
    if "cache=unsafe" in joined or "ignore_flush=" in joined or "-no-flush" in args:
        raise ValueError("unsafe QEMU cache or flush-bypass setting is not permitted")
    data_drives = [item for item in args if item.startswith("file=nbd://")]
    if not data_drives or not all("cache=writeback" in item for item in data_drives):
        raise ValueError("every NBD data drive must use QEMU cache=writeback")
    devices = [item for item in args if item.startswith("virtio-blk-pci,") and "CRASHLAB-NBD" in item]
    if not devices or not all("write-cache=on" in item for item in devices):
        raise ValueError("the NBD virtio block device must advertise write-cache=on")


def require_free_tcp_ports(host: str, ports: Sequence[int]) -> None:
    for port in ports:
        with socket.socket() as probe:
            probe.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 0)
            try:
                probe.bind((host, port))
            except OSError as error:
                raise OSError(f"TCP port {port} is unavailable on {host}") from error


def add_seed_iso_builder_argument(parser: argparse.ArgumentParser) -> None:
    group = parser.add_mutually_exclusive_group(required=True)
    group.add_argument("--hdiutil", type=Path, help="macOS hdiutil executable for cloud-init seed ISOs")
    group.add_argument("--genisoimage", type=Path, help="Linux genisoimage executable for cloud-init seed ISOs")


def resolve_seed_iso_builder(args: argparse.Namespace) -> tuple[Path, str]:
    hdiutil = getattr(args, "hdiutil", None)
    genisoimage = getattr(args, "genisoimage", None)
    if (hdiutil is None) == (genisoimage is None):
        raise ValueError("select exactly one seed ISO builder: --hdiutil or --genisoimage")
    if genisoimage is not None:
        return genisoimage, "genisoimage"
    return hdiutil, "hdiutil"


def create_seed_iso(iso_tool: Path, qemu_root: Path, name: str, boot_script: str, *, builder: str) -> Path:
    if Path(boot_script).name != boot_script or not boot_script.endswith(".sh"):
        raise ValueError("boot script must be a safe shell-script basename")
    seed_dir = qemu_root / f"{name}-seed"
    seed_dir.mkdir()
    template = (Path(__file__).resolve().parent / "guest/bootstrap-user-data.yaml.in")
    user_data = template.read_text(encoding="utf-8").replace("@BOOT_SCRIPT@", boot_script)
    if "@BOOT_SCRIPT@" in user_data:
        raise ValueError("cloud-init template was not fully rendered")
    write_text_exclusive(seed_dir / "user-data", user_data)
    instance_id = f"rdf4j-crashlab-{name}-{uuid.uuid4()}"
    write_text_exclusive(seed_dir / "meta-data", f"instance-id: {instance_id}\nlocal-hostname: rdf4j-crashlab\n")
    output = qemu_root / f"{name}-seed.iso"
    if builder == "hdiutil":
        command = [str(iso_tool), "makehybrid", "-iso", "-joliet", "-default-volume-name", "cidata",
                   "-o", str(output), str(seed_dir)]
    elif builder == "genisoimage":
        command = [str(iso_tool), "-output", str(output), "-volid", "cidata", "-joliet", "-rock", str(seed_dir)]
    else:
        raise ValueError(f"unsupported cloud-init seed ISO builder: {builder}")
    run_checked(command, log_path=qemu_root / f"{name}-seed-iso.log")
    if not output.is_file():
        raise FileNotFoundError(f"{builder} did not create the expected seed ISO: {output}")
    return output


def create_qcow_overlay(qemu_img: Path, base_image: Path, overlay: Path, log_path: Path) -> None:
    if overlay.exists():
        raise FileExistsError(f"refusing preexisting qcow2 overlay: {overlay}")
    run_checked([str(qemu_img), "create", "-f", "qcow2", "-F", "qcow2",
                 "-b", str(base_image), str(overlay)], log_path=log_path)


def guest_qemu_arguments(*, qemu: Path, name: str, machine: str = "virt", accel: str, cpu: str,
                         smp: int, memory_mib: int,
                         firmware_code: Path, firmware_vars: Path, os_disk: Path, data_port: int,
                         seed_iso: Path, serial_log: Path, repo_root: Path, results: Path) -> list[str]:
    if machine not in {"virt", "q35"}:
        raise ValueError(f"unsupported QEMU guest machine: {machine}")
    values = [firmware_code, firmware_vars, os_disk, seed_iso, serial_log, repo_root, results]
    if any("," in str(path) for path in values):
        raise ValueError("QEMU input paths may not contain commas")
    args = [str(qemu), "-name", name, "-machine", machine, "-accel", accel, "-cpu", cpu,
            "-smp", str(smp), "-m", str(memory_mib), "-display", "none", "-monitor", "none",
            "-serial", f"file:{serial_log}", "-no-reboot",
            "-drive", f"if=pflash,format=raw,unit=0,file={firmware_code},readonly=on",
            "-drive", f"if=pflash,format=raw,unit=1,file={firmware_vars}",
            "-drive", f"file={os_disk},format=qcow2,if=none,id=osdisk,cache=writeback",
            "-device", "virtio-blk-pci,drive=osdisk,bootindex=0",
            "-drive", f"file=nbd://127.0.0.1:{data_port}/crashlab,format=raw,if=none,id=datadisk,cache=writeback,werror=report,rerror=report",
            "-device", "virtio-blk-pci,drive=datadisk,write-cache=on,serial=CRASHLAB-NBD",
            "-drive", f"file={seed_iso},format=raw,if=none,id=seed,readonly=on",
            "-device", "virtio-blk-pci,drive=seed,serial=CRASHLAB-SEED",
            "-fsdev", f"local,id=repo,path={repo_root},security_model=none,readonly=on",
            "-device", "virtio-9p-pci,fsdev=repo,mount_tag=repo_ro",
            "-fsdev", f"local,id=m2,path={repo_root / '.m2_repo'},security_model=none,readonly=on",
            "-device", "virtio-9p-pci,fsdev=m2,mount_tag=m2_ro",
            "-fsdev", f"local,id=results,path={results},security_model=none",
            "-device", "virtio-9p-pci,fsdev=results,mount_tag=run_results",
            "-netdev", "user,id=net0", "-device", "virtio-net-pci,netdev=net0"]
    validate_qemu_arguments(args)
    return args


def start_logged_process(command: Sequence[str], log_path: Path) -> subprocess.Popen[bytes]:
    with log_path.open("xb") as log:
        process = subprocess.Popen(command, stdout=log, stderr=subprocess.STDOUT, start_new_session=True)
    return process


def wait_for_path(process: subprocess.Popen[bytes], paths: Sequence[Path], timeout: float,
                  *, process_may_exit: bool = False) -> Path:
    deadline = time.monotonic() + timeout
    while time.monotonic() < deadline:
        for path in paths:
            if path.exists():
                return path
        if process.poll() is not None and not process_may_exit:
            raise RuntimeError(f"process exited before marker appeared: {process.returncode}")
        time.sleep(0.1)
    raise TimeoutError("timed out waiting for one of: " + ", ".join(str(path) for path in paths))


def stop_process(process: subprocess.Popen[bytes] | None, sig: int = signal.SIGKILL,
                 timeout: float = 15) -> None:
    """Stop and reap a logged command plus any wrapped child processes it started."""
    if process is None:
        return

    group_id = process.pid

    def group_exists() -> bool:
        try:
            os.killpg(group_id, 0)
            return True
        except ProcessLookupError:
            return False
        except PermissionError:
            return True

    def signal_group(group_signal: int) -> None:
        try:
            os.killpg(group_id, group_signal)
        except ProcessLookupError:
            if process.poll() is None:
                process.send_signal(group_signal)

    if process.poll() is None or group_exists():
        signal_group(sig)

    deadline = time.monotonic() + timeout
    while group_exists() and time.monotonic() < deadline:
        if process.poll() is None:
            try:
                process.wait(timeout=min(0.05, max(0.0, deadline - time.monotonic())))
            except subprocess.TimeoutExpired:
                pass
        else:
            time.sleep(min(0.05, max(0.0, deadline - time.monotonic())))

    if group_exists():
        signal_group(signal.SIGKILL)
    if process.poll() is None:
        process.wait(timeout=10)

    reap_deadline = time.monotonic() + 2
    while group_exists() and time.monotonic() < reap_deadline:
        time.sleep(0.02)
    if group_exists():
        raise RuntimeError(f"process group {group_id} remained after SIGKILL")


def fence_nbd_then_stop_guest(guest: subprocess.Popen[bytes], fence_nbd: Callable[[], Any]) -> Any:
    """Cut and disconnect the virtual block device before abruptly stopping its guest."""
    try:
        cut_result = fence_nbd()
    except BaseException as cut_error:
        try:
            stop_process(guest, signal.SIGKILL)
        except BaseException as stop_error:
            raise cut_error from stop_error
        raise
    stop_process(guest, signal.SIGKILL)
    return cut_result


def start_backend(*, python: Path, backend: Path, image: Path, control: Path, port: int,
                  events: Path, log: Path, command_record: Path) -> subprocess.Popen[bytes]:
    for path in (control, events, log, command_record):
        if path.exists() or path.is_symlink():
            raise FileExistsError(f"refusing preexisting backend artifact: {path}")
    command = [str(python), "-u", str(backend), "serve", "--image", str(image),
               "--control", str(control), "--port", str(port), "--log", str(events)]
    process = start_logged_process(command, log)
    deadline = time.monotonic() + 10
    while time.monotonic() < deadline:
        if control.exists():
            write_json_exclusive(command_record, command)
            return process
        if process.poll() is not None:
            raise RuntimeError(f"NBD backend exited during startup with status {process.returncode}")
        time.sleep(0.05)
    raise TimeoutError(f"NBD backend control socket did not appear: {control}")


def backend_control(python: Path, backend: Path, control_path: Path, action: str,
                    *extra: str) -> dict[str, Any]:
    command = [str(python), str(backend), "ctl", "--control", str(control_path), action, *extra]
    result = subprocess.run(command, check=True, capture_output=True, text=True)
    return json.loads(result.stdout)


def run_checked(command: Sequence[str], *, log_path: Path | None = None) -> subprocess.CompletedProcess[str]:
    if log_path is None:
        return subprocess.run(command, check=True, capture_output=True, text=True)
    with log_path.open("x", encoding="utf-8") as log:
        result = subprocess.run(command, check=False, stdout=log, stderr=subprocess.STDOUT, text=True)
        log.flush()
        os.fsync(log.fileno())
    if result.returncode:
        raise subprocess.CalledProcessError(result.returncode, command)
    return result
